/* Evidence-based Atlas. The game runtime and its saves remain in play.html. */
'use strict';
(() => {
const ROOT='./assets/atlas-2026/';
const LABEL={D:'Есть прямо',P:'Есть частично',I:'Только косвенно',N:'Не найдено',U:'Требует проверки'};
const SHORT={D:'Прямо',P:'Частично',I:'Косвенно',N:'Не найдено',U:'Проверить'};
const RANK={D:4,P:3,I:2,N:1,U:0}, CODES=['D','P','I','N'];
const SOURCE={c39:'ФТ сервиса 39',ftt571:'ФТТ 57.1',dt25:'ДТ 2.5',ftt2026:'ФТТ 02.11.2026'};
const DEFAULT_STATE={workspace:'cmpon',view:'map',source:'ftt571',status:'all',query:'',section:'all',queue:'all',confidence:'all',group:'all',concept:null,page:1,question:0,questionFilter:'all',questionSection:'all',selected:null,geo:null};
const S={...DEFAULT_STATE};
const VIEWS=['map','requirements','cosmos','questions','stats','methods','reverse','glossary'];
const HASH_FIELDS={q:'query',section:'section',source:'source',status:'status',queue:'queue',confidence:'confidence',group:'group',concept:'concept',page:'page',question:'question',questionFilter:'questionFilter',questionSection:'questionSection',geo:'geo'};
let DB={meta:null,cmpon:[],other:null,reverse:[],questions:[],evidence:{}},toastTimer,otherPromise;
const STORAGE='cmpon-atlas-2026-review-v1';
let LOCAL={notes:{},answers:{}};
try{const value=JSON.parse(localStorage.getItem(STORAGE)||'null');if(value&&typeof value==='object'&&value.notes&&value.answers)LOCAL=value}catch{}
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v??'').toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const selected=(a,b)=>a===b?' selected':'';
const badge=s=>`<span class="badge ${s}"><i class="status-dot"></i>${LABEL[s]||LABEL.U}</span>`;
const action=(a,v,label,cls='button')=>`<button class="${cls}" data-action="${a}" data-value="${esc(v)}">${label}</button>`;
const fmt=n=>Number(n).toLocaleString('ru-RU');
const sourceList=()=>S.view==='reverse'?['ftt2026']:S.workspace==='cmpon'?['c39','ftt571','dt25']:['c39','ftt571'];
const currentRows=()=>S.view==='reverse'?DB.reverse:S.workspace==='cmpon'?DB.cmpon:(DB.other||[]);
const mapping=(r,source)=>r.maps?.[source]||{status:'U',confidence:'Низкая',refs:[],reason:'Проверка еще не завершена.',missing:''};
function status(r,source=S.source){if(source==='best')return sourceList().map(s=>mapping(r,s).status).sort((a,b)=>RANK[b]-RANK[a])[0]||'U';return mapping(r,source).status}
function confidence(r){if(S.source!=='best')return mapping(r,S.source).confidence;const src=sourceList().sort((a,b)=>RANK[mapping(r,b).status]-RANK[mapping(r,a).status])[0];return mapping(r,src).confidence}
function count(rows=currentRows(),source=S.source){const c={D:0,P:0,I:0,N:0,U:0};for(const r of rows)c[status(r,source)]++;return c}
function scopeName(){return S.source==='best'?'Сильнейшее основание':SOURCE[S.source]}
function allRows(){return [...DB.cmpon,...(DB.other||[]),...DB.reverse]}
function findRow(id){return allRows().find(r=>r.id===id)}
function queueLabel(r){if(r.scopeKind==='declared_implemented')return 'Заявлено как реализованное';if(r.queue)return `Очередь ${r.queue}`;return r.scopeLabel||'Общие требования'}
function sectionRoot(r){const p=String(r.section).split('.');return p.length>=2?p.slice(0,2).join('.'):p[0]}
function searchMatches(r){
 if(!S.query.trim())return true;
 const topics=(r.concepts||[]).flatMap(id=>{const c=DB.meta.concepts.find(c=>c.id===id);return c?[c.id,c.title]:[]});
 const hay=norm([r.id,r.text,r.continuation,r.section,r.sectionTitle,...topics,...Object.values(r.maps||{}).flatMap(m=>[m.reason,m.missing,...(m.relatedIds||[]),...(m.refs||[])])].join(' '));
 return norm(S.query).split(' ').every(t=>hay.includes(t));
}
function filtered(rows=currentRows()){return rows.filter(r=>searchMatches(r)&&(S.status==='all'||status(r)===S.status)&&(S.section==='all'||r.section===S.section||sectionRoot(r)===S.section)&&(S.view==='reverse'||S.queue==='all'||(S.queue==='implemented'?r.scopeKind==='declared_implemented':String(r.queue||'general')===S.queue))&&(S.confidence==='all'||confidence(r)===S.confidence)&&(!S.concept||(r.concepts||[]).includes(S.concept))&&(S.group==='all'||(r.groups||[]).includes(S.group)))}
function saveLocal(){try{localStorage.setItem(STORAGE,JSON.stringify(LOCAL));return true}catch{toast('Браузер не сохранил изменения. Текст остался в поле: скопируйте его или повторите сохранение.');return false}}
function saveEntry(collection,id,value){
 const previous=LOCAL[collection][id],existed=Object.prototype.hasOwnProperty.call(LOCAL[collection],id);
 LOCAL[collection][id]=value;
 if(saveLocal())return true;
 if(existed)LOCAL[collection][id]=previous;else delete LOCAL[collection][id];
 return false;
}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3800)}
function reset(){Object.assign(S,{status:'all',query:'',section:'all',queue:'all',confidence:'all',group:'all',concept:null,page:1});$('search').value='';render()}
function hash(){
 const p=new URLSearchParams();
 for(const [key,field] of Object.entries(HASH_FIELDS))if(S[field]!==DEFAULT_STATE[field]&&S[field]!=null)p.set(key,String(S[field]));
 const suffix=p.toString();
 history.replaceState(null,'',`#${S.workspace}/${S.view}${suffix?'?'+suffix:''}`);
}
function readHash(){
 const raw=location.hash.replace(/^#/,''),split=raw.indexOf('?'),path=split<0?raw:raw.slice(0,split),p=new URLSearchParams(split<0?'':raw.slice(split+1)),bits=path.split('/');
 Object.assign(S,DEFAULT_STATE);
 if(['cmpon','other'].includes(bits[0])){S.workspace=bits[0];if(VIEWS.includes(bits[1]))S.view=bits[1]}else if(VIEWS.includes(path))S.view=path;
 if(S.workspace==='other'&&['reverse','cosmos','glossary'].includes(S.view))S.view='map';
 const pick=(key,allowed,fallback)=>allowed.includes(p.get(key))?p.get(key):fallback;
 const integer=(key,min,fallback)=>{const value=p.get(key);return value!==null&&/^\d+$/.test(value)&&Number.isSafeInteger(Number(value))&&Number(value)>=min?Number(value):fallback};
 S.query=p.get('q')||'';
 S.section=/^\d+(?:\.\d+)*$/.test(p.get('section')||'')?p.get('section'):'all';
 S.source=S.view==='reverse'?'ftt2026':pick('source',['best',...sourceList()],'ftt571');
 S.status=pick('status',['all',...CODES],'all');
 S.queue=S.view==='reverse'?'all':pick('queue',['all','implemented','1','2','3','4','general'],'all');
 S.confidence=pick('confidence',['all','Высокая','Средняя','Низкая'],'all');
 if(S.workspace==='cmpon'){
  S.group=pick('group',['all',...DB.meta.groups.map(g=>g.id)],'all');
  S.concept=pick('concept',DB.meta.concepts.map(c=>c.id),null);
  S.geo=pick('geo',DB.meta.geoLands.map(g=>g.id),null);
 }
 S.page=integer('page',1,1);S.question=integer('question',0,0);
 S.questionFilter=pick('questionFilter',['all','unanswered'],'all');
 if(S.workspace==='other')S.questionSection=pick('questionSection',['all',...new Set(DB.questions.filter(q=>q.scope==='other').flatMap(q=>q.sections||[]))],'all');
}
function nav(){const items=[['map','Карта оснований','▦'],['requirements','Все требования','≡'],...(S.workspace==='cmpon'?[['cosmos','География требований','◎'],['reverse','Сохранность ДТ 2.5','↔'],['glossary','Термины и объекты','◇']]:[]),['questions','Вопросы для решения','?'],['stats','Статистика','▥'],['methods','Источники и методика','⌕']];$('nav').innerHTML=items.map(([v,t,i])=>`<button class="nav-item ${v===S.view?'active':''}" data-action="view" data-value="${v}" ${v===S.view?'aria-current="page"':''}><span aria-hidden="true">${i}</span><span>${t}</span><small>${v==='requirements'?fmt((S.workspace==='cmpon'?DB.cmpon:DB.other||[]).length):v==='questions'?questions().length:v==='reverse'?DB.reverse.length:''}</small></button>`).join('');$('crumb').textContent=(S.workspace==='cmpon'?'ЦМПОН':'Другие направления')+' / '+(items.find(i=>i[0]===S.view)?.[1]||'Карта');document.querySelectorAll('[data-action="workspace"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===S.workspace);b.setAttribute('aria-pressed',String(b.dataset.value===S.workspace))})}
function renderChrome(){nav();const reverse=S.view==='reverse',cmpon=S.workspace==='cmpon';$('eyebrow').textContent=reverse?'ДТ 2.5 → НОВЫЙ ФТТ · ОБРАТНАЯ ПРОВЕРКА':cmpon?'ФТТ 02.11.2026 · С39 · ФТТ 57.1 · ДТ 2.5':'ФТТ 02.11.2026 · С39 · ФТТ 57.1';$('title').innerHTML=reverse?'Что сохранено из ДТ<span>.</span>':cmpon?'Основания требований<span>.</span>':'Другие направления<span>.</span>';$('intro').textContent=reverse?'Для каждого исходного требования ДТ 2.5 проверены новый блок ЦМПОН и общие компоненты ГИС ЦАП. Здесь видны сокращенные и не найденные условия.':cmpon?'Новый ФТТ в основе карты. Точные формулировки, предшествующие основания и смысловые различия. Привычные темы и география сохранены.':'Отдельный каталог остальных разделов ГИС ЦАП. Сопоставление с ФТ сервиса 39 и ФТТ 57.1; ДТ 2.5 в эти оценки не включается.';const list=sourceList();if(reverse)S.source='ftt2026';else if(!list.includes(S.source)&&S.source!=='best')S.source='ftt571';$('scope').innerHTML=(reverse?'':`<option value="best"${selected('best',S.source)}>Сильнейшее из ${list.length} источников</option>`)+list.map(s=>`<option value="${s}"${selected(s,S.source)}>${SOURCE[s]}</option>`).join('');$('search').value=S.query;const hide=['questions','methods','glossary'].includes(S.view);$('scope-bar').hidden=hide;$('top-export').hidden=hide;$('metrics').hidden=hide;$('summary-caption').hidden=hide;if(hide)return;const rows=currentRows(),c=count(rows),captions=reverse?{D:'Все условия исходного требования',P:'Часть условий не сохранена',I:'Только общее / косвенное положение',N:'В проверенной редакции не найдено'}:{D:'Все существенные условия прямо',P:'Функция есть, часть условий отсутствует',I:'Связь требует расширительной трактовки',N:'Прямое основание не найдено'};$('metrics').innerHTML=CODES.map(code=>`<button class="metric ${code} ${S.status===code?'active':''}" data-action="metric" data-value="${code}"><span class="metric-title"><i class="status-dot"></i>${LABEL[code]}</span><strong>${fmt(c[code])}<small>${rows.length?(c[code]/rows.length*100).toFixed(1).replace('.',','):0}%</small></strong><span class="metric-foot">${captions[code]}</span></button>`).join('');$('summary-caption').innerHTML=`<span>${fmt(rows.length)} требований ${reverse?'ДТ 2.5':cmpon?'ЦМПОН':'остальных разделов'} · ${esc(scopeName())}. ${S.source==='best'?'Выбрана сильнейшая отдельная оценка; условия разных источников автоматически не складываются.':'Показатели по всей выбранной области, до фильтров.'}${c.U?` <strong>Не завершено: ${c.U}.</strong>`:''}</span>${action('reset','','Сбросить фильтры ↺','text-button')}`}
function legend(){return `<div class="legend-filters">${action('status','all','Все оценки',`legend-filter ${S.status==='all'?'active':''}`)}${CODES.map(s=>action('status',s,`<i class="status-dot"></i>${LABEL[s]}`,`legend-filter ${s} ${S.status===s?'active':''}`)).join('')}</div>`}
function miniBar(rows,src){const c=count(rows,src);return `<span class="concept-mix">${c.D} прямо · ${c.P} частично</span><span class="mini-bar" aria-label="${c.D} прямо, ${c.P} частично, ${c.I} косвенно, ${c.N} не найдено">${CODES.map(s=>`<span class="${s}" style="width:${rows.length?c[s]/rows.length*100:0}%"></span>`).join('')}</span>`}
function renderMap(){if(S.workspace==='other')return renderChapters();const rows=filtered(),visible=new Set(rows.map(r=>r.id)),conceptRows=new Map(DB.meta.concepts.map(c=>[c.id,rows.filter(r=>(r.concepts||[]).includes(c.id))]));const concepts=DB.meta.concepts.filter(c=>(S.group==='all'||c.group===S.group)&&conceptRows.get(c.id).length);return `<div class="topology"><section class="topology-main"><div class="section-title"><div><h2>Топография требований</h2><p>Один квадрат: одно требование нового ФТТ. Нажмите, чтобы открыть сопоставление.</p></div><small>${fmt(rows.length)} / ${fmt(DB.cmpon.length)} ФТ</small></div><div class="heatmap">${DB.cmpon.map(r=>`<button class="tile ${status(r)} ${visible.has(r.id)?'':'faded'}" data-action="requirement" data-value="${esc(r.id)}" title="${esc(r.id+' · '+LABEL[status(r)]+'\n'+r.text)}" aria-label="${esc(r.id+': '+LABEL[status(r)]+'. '+r.text)}"></button>`).join('')}</div><div class="map-help"><span>Идентификатор требования и пункт оглавления показаны раздельно.</span>${action('filtered-requirements','',`К списку ${fmt(rows.length)} →`,'text-button')}</div></section><aside class="insight"><p class="eyebrow">ПРОВЕРКА В ОБЕ СТОРОНЫ</p><h3>Основание есть.<br>Все ли условия сохранены?</h3><p>Новый сокращенный пункт может опираться на ДТ. Это еще не значит, что исходное требование перенесено полностью.</p>${action('view','reverse','Проверить сохранность ДТ ↗')}</aside></div><div class="section-title"><div><h2>Карта концепций</h2><p>Темы прежней карты связаны с требованиями новой редакции.</p></div><small>${concepts.length} / ${DB.meta.concepts.length} тем · 4 документа</small></div><div class="groups">${DB.meta.groups.map(g=>{const n=rows.filter(r=>(r.groups||[]).includes(g.id)).length;return action('group',g.id,`<span>${esc(g.title)}<small>${n} требований</small></span>`, `group ${S.group===g.id?'active':''}`)}).join('')}</div>${legend()}<div class="concept-list"><div class="concept-list-head"><span>КОНЦЕПЦИЯ · СОСТАВ И ОСНОВАНИЯ</span><span>ФТ СЕРВИСА 39</span><span>ФТТ 57.1</span><span>ДТ 2.5</span></div>${concepts.map(c=>{const rs=conceptRows.get(c.id);return `<button class="concept-node" data-action="concept" data-value="${c.id}"><span class="concept-label"><small>${c.id}</small><strong>${esc(c.title)}</strong><span class="subtle"> · ${rs.length}</span></span>${['c39','ftt571','dt25'].map(src=>`<span>${miniBar(rs,src)}</span>`).join('')}</button>`}).join('')}</div><p class="atlas-note">Концепции пересекаются. Счётчики и полосы учитывают действующие фильтры и показывают оценки связанных требований, а не единую оценку всей темы.</p>`}
function chapterFilters(){const rows=currentRows();const secs=new Map();for(const r of rows)if(!secs.has(r.section))secs.set(r.section,r.sectionTitle);return `<div class="filters"><label>Раздел<select id="section-filter"><option value="all">Все разделы</option>${[...secs].map(([id,title])=>`<option value="${esc(id)}"${selected(id,S.section)}>${esc(id+' '+title)}</option>`).join('')}</select></label>${S.view!=='reverse'?`<label>Очередь / статус<select id="queue-filter"><option value="all">Все</option><option value="implemented"${selected('implemented',S.queue)}>Заявлено как реализованное</option>${[1,2,3,4].map(q=>`<option value="${q}"${selected(String(q),S.queue)}>Очередь ${q}</option>`).join('')}<option value="general"${selected('general',S.queue)}>Общие / технические</option></select></label>`:''}<label>Достоверность<select id="confidence-filter"><option value="all">Любая</option>${['Высокая','Средняя','Низкая'].map(v=>`<option${selected(v,S.confidence)}>${v}</option>`).join('')}</select></label>${S.concept?`<span class="filter-chip">${esc(DB.meta.concepts.find(c=>c.id===S.concept)?.title||S.concept)} ${action('clear-concept','','×','text-button')}</span>`:''}${S.group!=='all'?action('group','all','Все темы','button'):''}</div>`}
function empty(title='Ничего не найдено',message='Измените запрос или сбросьте фильтры.'){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(message)}</p>${action('reset','','Сбросить фильтры')}</div>`}
function renderTable(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/40));S.page=Math.min(Math.max(S.page,1),pages);const srcs=sourceList(),reverse=S.view==='reverse';return `<div class="section-title"><div><h2>${reverse?'Учет исходных требований ДТ 2.5':'Все требования'}</h2><p>${reverse?'Оценка сохранности полного исходного требования, включая существенные условия.':'Текст документа, точная привязка и отдельная оценка по каждому источнику.'}</p></div><small>${fmt(rows.length)} / ${fmt(currentRows().length)}</small></div>${chapterFilters()}${legend()}${rows.length?`<div class="table-wrap"><table><thead><tr><th>${reverse?'ID ДТ':'ID / пункт'}</th><th>Требование</th>${srcs.map(s=>`<th>${SOURCE[s]}</th>`).join('')}</tr></thead><tbody>${rows.slice((S.page-1)*40,S.page*40).map(r=>`<tr class="req-row" tabindex="0" role="button" data-action="requirement" data-value="${esc(r.id)}" aria-label="Открыть ${esc(r.id)}"><td><span class="req-id">${esc(r.id)}</span><br><small>п. ${esc(r.section)}</small>${r.numbered===false?'<br><small class="subtle">ID атласа, не документа</small>':''}</td><td class="req-text"><div class="clamp">${esc(r.text)}</div><small>${esc(r.sectionTitle)}</small>${!reverse?`<span class="queue-chip">${esc(queueLabel(r))}</span>`:''}${r.qualityFlags?.length?'<span class="question-dot">Есть вопрос к тексту</span>':''}</td>${srcs.map(s=>`<td>${badge(mapping(r,s).status)}<br><small class="subtle">${esc(mapping(r,s).confidence)}</small></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pagination">${action('page','-1','← Назад')}<span>Страница ${S.page} из ${pages}</span>${action('page','1','Далее →')}</div>`:empty()}`}
function renderChapters(){const rows=filtered(),chapters=new Map();for(const r of rows){const id=sectionRoot(r);if(!chapters.has(id))chapters.set(id,[]);chapters.get(id).push(r)}return `<div class="notice">Разделы различаются по статусу: архитектура, функции, заявленные как реализованные, очереди 1–4 и общесистемные требования. Совпадение текста не подтверждает фактическую реализацию.</div><div class="section-title"><div><h2>Направления и разделы</h2><p>Выберите область. ЦМПОН ведется в основной вкладке и в эти числа не входит.</p></div><small>${fmt(rows.length)} требований</small></div>${chapterFilters()}${legend()}<div class="chapter-grid">${[...chapters].map(([id,rs])=>{const label=DB.meta.sectionTitles?.[id]||rs[0].chapterTitle||rs[0].sectionTitle;return `<button class="chapter-card" data-action="chapter" data-value="${id}"><small>РАЗДЕЛ ${esc(id)} · ${esc(queueLabel(rs[0]))}</small><h3>${esc(label)}</h3><strong>${fmt(rs.length)}</strong><small> требований</small>${miniBar(rs,S.source)}</button>`}).join('')}</div>`}
function evidenceHtml(keys=[]){return [...new Set(keys)].map(key=>{const e=DB.evidence[key];if(!e)return `<p class="subtle">Ссылка ${esc(key)} отсутствует в пакете.</p>`;return `<article class="evidence-quote"><div class="evidence-meta"><b>${esc(SOURCE[e.source]||e.source)}</b><span>п. ${esc(e.section||'без номера')}</span><span>${esc(e.label||'')}</span><span>${esc(key)}</span></div><blockquote>${esc(e.text)}</blockquote></article>`}).join('')}
function sourceCard(r,src){const m=mapping(r,src);return `<section class="source-card"><div class="source-card-head"><div><h4>${SOURCE[src]}</h4><small>Достоверность: ${esc(m.confidence)}</small></div>${badge(m.status)}</div><div class="source-card-body"><p>${esc(m.reason)}</p>${m.scopeDifference?`<div class="notice"><strong>Область и очередь</strong><p>${esc(m.scopeDifference)}</p></div>`:''}${m.missing?`<div class="missing"><strong>Что не подтверждено</strong><p>${esc(m.missing)}</p></div>`:''}${m.relatedIds?.length?`<p class="refs">ID источника: ${esc(m.relatedIds.join('; '))}</p>`:''}<details class="quote-disclosure"><summary>Показать цитаты · ${m.refs?.length||0}</summary>${m.refs?.length?evidenceHtml(m.refs):'<p class="subtle">Подтверждающее положение в проверенной редакции не найдено. Это вывод о документе, а не доказательство отсутствия функции.</p>'}</details></div></section>`}
function questionLinks(id){return DB.questions.filter(q=>(q.requirementIds||[]).includes(id))}
async function openRequirement(id){let r=findRow(id);if(!r&&(DB.meta.otherRequirementIds||[]).includes(id)){await ensureOther();r=findRow(id)}if(!r){toast('Не удалось открыть требование');return;}S.selected={kind:'requirement',id};const reverse=r.source==='dt25',srcs=reverse?['ftt2026']:r.maps?.dt25?['c39','ftt571','dt25']:['c39','ftt571'];const note=LOCAL.notes[id]||{};const questionsForRow=questionLinks(id);$('drawer-type').textContent=reverse?'СОХРАННОСТЬ ИСХОДНОГО ТРЕБОВАНИЯ':'ОСНОВАНИЯ НОВОГО ТРЕБОВАНИЯ';$('detail-body').innerHTML=`<div class="drawer-kicker"><span>${esc(reverse?'ДТ 2.5':'ФТТ 02.11.2026')}</span><span>Пункт оглавления: ${esc(r.section)}</span>${r.numbered===false?'<span>ID присвоен в атласе</span>':`<span>ID документа: ${esc(r.id)}</span>`}</div><h2 class="drawer-title" id="detail-title">${esc(r.id)}</h2><p class="subtle">${esc(r.sectionTitle)}${reverse?'':' · '+esc(queueLabel(r))}</p><blockquote class="requirement-quote">${esc(r.text)}${r.continuation?'\n\n'+esc(r.continuation):''}</blockquote>${r.qualityFlags?.length?`<div class="notice">${r.qualityFlags.map(esc).join('<br>')}${r.qualityRefs?.length?`<details class="quote-disclosure"><summary>Основания замечания к тексту</summary>${evidenceHtml(r.qualityRefs)}</details>`:''}</div>`:''}<p class="subtle">${reverse?'Проверяется полнота сохранения исходного требования в новом ФТТ, в том числе в общих компонентах.':'Проверяется наличие всех условий нового требования в каждом прежнем источнике. Потерянные условия ДТ показаны в обратной проверке.'}</p><div class="source-grid ${srcs.length!==3?'two':''}">${srcs.map(src=>sourceCard(r,src)).join('')}</div>${questionsForRow.length?`<h3>Вопросы для решения</h3><div class="related">${questionsForRow.map(q=>action('question-open',q.id,esc(q.title)+' ↗')).join('')}</div>`:''}${r.concepts?.length?`<h3>Связанные темы</h3><div class="related">${r.concepts.map(id=>action('concept',id,esc(DB.meta.concepts.find(c=>c.id===id)?.title||id))).join('')}</div>`:''}<details class="quote-disclosure"><summary>Исходная привязка в документе</summary>${evidenceHtml(r.sourceKeys||[r.key])}</details><section class="review-box"><h3>Моя рецензия</h3><label>Оценка вывода <select id="review-state"><option value="unreviewed"${selected(note.status,'unreviewed')}>Еще не проверено</option><option value="agree"${selected(note.status,'agree')}>Согласен с выводом</option><option value="dispute"${selected(note.status,'dispute')}>Есть возражение</option><option value="clarify"${selected(note.status,'clarify')}>Нужно уточнение</option></select></label><label for="review-note">Комментарий</label><textarea id="review-note" placeholder="Что следует уточнить или исправить…">${esc(note.text||'')}</textarea>${action('save-review',id,'Сохранить рецензию','button primary')}<p class="decision-note">Рецензия хранится в этом браузере. Исходные оценки не меняются автоматически; решения можно выгрузить.</p></section>`;const dlg=$('detail');if(!dlg.open)dlg.showModal();dlg.scrollTop=0}
function openConcept(id){const c=DB.meta.concepts.find(c=>c.id===id);if(!c)return;const allConceptRows=DB.cmpon.filter(r=>(r.concepts||[]).includes(id)),usesFilters=S.workspace==='cmpon'&&['map','requirements','cosmos'].includes(S.view),rows=usesFilters?filtered(allConceptRows):allConceptRows;S.selected={kind:'concept',id,rowIds:rows.map(r=>r.id)};$('drawer-type').textContent='КОНЦЕПЦИЯ / '+id;$('detail-body').innerHTML=`<div class="drawer-kicker"><span>${esc(DB.meta.groups.find(g=>g.id===c.group)?.title||'')}</span><span>${rows.length} из ${allConceptRows.length} требований новой редакции${usesFilters?' · с учётом фильтров':''}</span></div><h2 class="drawer-title" id="detail-title">${esc(c.title)}</h2><p class="subtle">Оценки рассчитываются по отдельным связанным требованиям. Общая тема не доказывает наличие всех специальных условий.</p><div class="chart-grid">${['c39','ftt571','dt25'].map(src=>chart(rows,src)).join('')}</div><div class="related">${rows.map(r=>action('requirement',r.id,esc(r.id))).join('')}</div><div style="margin-top:20px">${action('concept-filter',id,'Показать требования в таблице →','button primary')}</div>`;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0}
function chart(rows,source){const c=count(rows,source);return `<section class="chart-panel"><h3>${esc(SOURCE[source]||scopeName())}</h3>${CODES.map(s=>`<div class="bar-row ${s}"><span>${SHORT[s]}</span><div class="bar-track"><div class="bar-fill" style="width:${rows.length?c[s]/rows.length*100:0}%"></div></div><b>${fmt(c[s])}</b></div>`).join('')}</section>`}
function renderStats(){const rows=currentRows(),sources=sourceList();return `<div class="section-title"><div><h2>Результаты сопоставления</h2><p>Направление сравнения: новое требование → его основания в прежнем документе.</p></div><small>${fmt(rows.length)} требований</small></div><div class="chart-grid">${sources.map(src=>chart(rows,src)).join('')}</div>${S.workspace==='cmpon'?`<div class="section-title"><div><h2>Обратная проверка ДТ 2.5</h2><p>Показывает сохранность исходных условий. Эти числа нельзя складывать с числом новых требований.</p></div>${action('view','reverse','Открыть все ДТ →')}</div>${chart(DB.reverse,'ftt2026')}`:''}<div class="section-title"><div><h2>По разделам нового ФТТ</h2><p>Выберите строку, чтобы открыть требования раздела.</p></div></div><div class="table-wrap"><table><thead><tr><th>Раздел</th><th>Количество</th>${sources.map(s=>`<th>${SOURCE[s]}: прямо / частично / косвенно / не найдено</th>`).join('')}</tr></thead><tbody>${[...new Set(rows.map(sectionRoot))].map(sec=>{const rs=rows.filter(r=>sectionRoot(r)===sec);return `<tr class="req-row" data-action="chapter" data-value="${sec}"><td>${esc(sec+' '+(DB.meta.sectionTitles?.[sec]||rs[0].sectionTitle))}</td><td>${rs.length}</td>${sources.map(src=>{const c=count(rs,src);return `<td>${CODES.map(s=>c[s]).join(' / ')}</td>`}).join('')}</tr>`}).join('')}</tbody></table></div><p class="stat-note">«Не найдено» относится к проверенной редакции документа. Наличие требования не подтверждает реализацию, приемку или согласованный договорной объем.</p>`}
/* Geography, decision cards, methods and event routing follow below. */
function inside(p,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes}
function edgeDistance(p,poly){return Math.min(...poly.map((a,i)=>{const b=poly[(i+1)%poly.length],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy)));return Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy)}))}
function bounds(g){const xs=g.points.map(p=>p[0]),ys=g.points.map(p=>p[1]);return{x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)}}
function landPath(g){const p=g.points,n=p.length,mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2];return 'M'+mid(p[n-1],p[0]).join(' ')+p.map((a,i)=>'Q'+a.join(' ')+' '+mid(a,p[(i+1)%n]).join(' ')).join('')+'Z'}
let GEO_LAYOUT;
function makeGeo(){
 GEO_LAYOUT=new Map();
 for(const g of DB.meta.geoLands){
  const b=bounds(g),concepts=DB.meta.concepts.filter(c=>c.group===g.id),rows=DB.cmpon.filter(r=>g.id==='unmapped'?!(r.groups||[]).length:(r.groups||[]).includes(g.id));
  let layout;
  for(const step of [11,9,7]){
   const grid=[];
   for(let y=b.y+16;y<b.y+b.h-14;y+=step)for(let x=b.x+16;x<b.x+b.w-14;x+=step)if(inside([x,y],g.points)&&edgeDistance([x,y],g.points)>18&&!(Math.abs(x-g.center[0])<100&&y<b.y+75))grid.push([x,y]);
   const cities=[];
   for(const c of concepts){let best=null,score=-Infinity;for(const p of grid){const d=cities.length?Math.min(...cities.map(q=>Math.hypot(q.x-p[0],q.y-p[1]))):-Math.hypot(p[0]-g.center[0],p[1]-g.center[1]);if(d>score){score=d;best=p}}if(best)cities.push({id:c.id,x:best[0],y:best[1]})}
   const pins=[],used=new Set();
   for(const r of rows){const city=cities.find(c=>(r.concepts||[]).includes(c.id)),center=city?[city.x,city.y]:g.center;let best=-1,score=Infinity;grid.forEach((p,i)=>{if(used.has(i)||cities.some(c=>Math.hypot(c.x-p[0],c.y-p[1])<17||(Math.abs(c.x-p[0])<12&&p[1]-c.y>8&&p[1]-c.y<26)))return;const d=Math.hypot(p[0]-center[0],p[1]-center[1]);if(d<score){score=d;best=i}});if(best>=0){used.add(best);pins.push({id:r.id,x:grid[best][0],y:grid[best][1],radius:step<9?2.9:3.8})}}
   layout={cities,pins,missing:rows.filter(r=>!pins.some(p=>p.id===r.id)).map(r=>r.id)};
   if(!layout.missing.length)break;
  }
  GEO_LAYOUT.set(g.id,layout);
 }
}
function uniqueGeoMissing(){return [...new Set([...GEO_LAYOUT.values()].flatMap(l=>l.missing))]}
function renderGeo(){if(!GEO_LAYOUT)makeGeo();const visible=new Set(filtered().map(r=>r.id));const land=DB.meta.geoLands.find(g=>g.id===S.geo);const view=land?(()=>{const b=bounds(land);return[b.x-25,b.y-25,b.w+50,b.h+50]})():[0,0,1200,830];return `<div class="section-title"><div><h2>География требований</h2><p>Прежняя карта сохранена. Города обозначают концепции, точки: связанные требования нового ФТТ.</p></div>${action('geo-reset','','Вся карта')}</div><div class="geo-shell"><div class="geo-toolbar"><p>${land?esc(land.name.join(' ')):'Обзор всех тематических областей'} · ${esc(scopeName())}</p><div>${action('geo-zoom','in','＋','button')}${action('geo-zoom','out','−','button')}</div></div><div class="geo-wrap"><svg id="geo-map" class="geo-map" viewBox="${view.join(' ')}" role="img" aria-label="Интерактивная география требований ЦМПОН"><defs><pattern id="geo-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d8e1d5" stroke-width=".6"/></pattern></defs><rect x="-1000" y="-1000" width="3200" height="3000" fill="#e9eee8"/><rect x="0" y="0" width="1200" height="830" fill="url(#geo-grid)"/>${DB.meta.geoLands.map(g=>{const layout=GEO_LAYOUT.get(g.id);return `<g><path class="geo-land" d="${landPath(g)}" fill="${g.color}" data-action="geo-land" data-value="${g.id}" tabindex="0" role="button" aria-label="Область ${esc(g.name.join(' '))}"><title>${esc(g.name.join(' '))}</title></path>${layout.pins.map(p=>{const r=DB.cmpon.find(r=>r.id===p.id);return `<circle class="geo-pin ${status(r)}" cx="${p.x}" cy="${p.y}" r="${p.radius}" opacity="${visible.has(p.id)?1:.12}" data-action="requirement" data-value="${esc(p.id)}" tabindex="0" role="button" aria-label="${esc(p.id)}"><title>${esc(p.id+' · '+LABEL[status(r)]+'\n'+r.text)}</title></circle>`}).join('')}${layout.cities.map(city=>`<g data-action="concept" data-value="${city.id}" tabindex="0" role="button" aria-label="${esc(DB.meta.concepts.find(c=>c.id===city.id)?.title)}"><circle class="geo-city" cx="${city.x}" cy="${city.y}" r="7"/><text class="geo-city-label" x="${city.x}" y="${city.y+20}">${city.id}</text><title>${esc(DB.meta.concepts.find(c=>c.id===city.id)?.title)}</title></g>`).join('')}<text class="geo-country-label" x="${g.center[0]}" y="${bounds(g).y+29}">${g.name.map((t,i)=>`<tspan x="${g.center[0]}" dy="${i?19:0}">${esc(t)}</tspan>`).join('')}</text></g>`}).join('')}</svg></div><div class="geo-legend">${CODES.map(s=>`<span class="${s}"><i class="status-dot"></i>${LABEL[s]}</span>`).join('')}<span>Колесо: масштаб · перетаскивание: перемещение</span></div></div>${[...GEO_LAYOUT.values()].some(l=>l.missing.length)?`<div class="notice">Точки вне видимой сетки: ${uniqueGeoMissing().map(id=>action('requirement',id,esc(id))).join(' ')}</div>`:''}<div class="geo-details">${DB.meta.groups.map(g=>action('geo-land',g.id,esc(g.title))).join('')}</div><p class="atlas-note">Одно требование может относиться к нескольким темам и показываться в нескольких областях. Число точек на всей карте не суммируется.</p>`}
function mountGeo(){const svg=$('geo-map');if(!svg)return;let drag=null,moved=false;const box=()=>svg.getAttribute('viewBox').split(/\s+/).map(Number);svg.addEventListener('wheel',e=>{e.preventDefault();const b=box(),factor=e.deltaY<0?.85:1.18,w=Math.min(1800,Math.max(120,b[2]*factor)),h=w*b[3]/b[2];svg.setAttribute('viewBox',[b[0]+(b[2]-w)/2,b[1]+(b[3]-h)/2,w,h].join(' '))},{passive:false});svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,b:box()};moved=false});svg.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5){moved=true;svg.setPointerCapture(e.pointerId);const r=svg.getBoundingClientRect();svg.setAttribute('viewBox',[drag.b[0]-dx/r.width*drag.b[2],drag.b[1]-dy/r.height*drag.b[3],drag.b[2],drag.b[3]].join(' '))}});svg.addEventListener('pointerup',()=>{drag=null});svg.addEventListener('pointercancel',()=>{drag=null});svg.addEventListener('click',e=>{if(moved){e.stopPropagation();moved=false}},true)}
function answer(q){const a=LOCAL.answers[q.id];return a&&(!q.signature||a.signature===q.signature)&&((q.options||[]).some(o=>o.id===a.option)||(typeof a.comment==='string'&&a.comment.trim()))?a:null}
function questions(){return DB.questions.filter(q=>(q.scope||'cmpon')===S.workspace&&(S.questionFilter!=='unanswered'||!answer(q))&&(S.questionSection==='all'||(q.sections||[]).includes(S.questionSection)))}
function renderQuestions(){const qs=questions(),all=DB.questions.filter(q=>(q.scope||'cmpon')===S.workspace),done=all.filter(q=>answer(q)).length;if(!qs.length)return `<div class="section-title"><div><h2>Вопросы для решения</h2><p>Сохраненные ответы: ${done} из ${all.length}.</p></div>${action('question-filter','all','Все карточки')}</div>${empty('Нет вопросов в выбранном фильтре','Ответы и рецензии можно выгрузить для следующей редакции.')}<div style="margin-top:16px">${action('export-decisions','','Выгрузить решения JSON')}</div>`;S.question=Math.min(Math.max(0,S.question),qs.length-1);const q=qs[S.question],a=answer(q);return `<div class="section-title"><div><h2>Вопросы для решения</h2><p>Каждая карточка содержит конкретное различие, цитаты и варианты. Ответ не меняет исходную оценку автоматически.</p></div>${action('export-decisions','','↓ Решения JSON')}</div><div class="legend-filters">${action('question-filter','all','Все вопросы',`legend-filter ${S.questionFilter==='all'?'active':''}`)}${action('question-filter','unanswered','Без ответа',`legend-filter ${S.questionFilter==='unanswered'?'active':''}`)}</div>${S.workspace==='other'?`<div class="filters"><label>Раздел вопросов<select id="question-section"><option value="all">Все разделы</option>${[...new Set(all.flatMap(q=>q.sections||[]))].sort((a,b)=>a.localeCompare(b,'ru',{numeric:true})).map(sec=>`<option value="${esc(sec)}"${selected(sec,S.questionSection)}>${esc(sec+' '+(DB.meta.sectionTitles[sec]||''))}</option>`).join('')}</select></label></div>`:''}<div class="question-layout"><aside class="question-index"><strong>${done} / ${all.length}</strong><p>Решений сохранено</p><div class="progress-track"><div style="width:${all.length?done/all.length*100:0}%"></div></div><div class="question-index-list">${qs.map((item,i)=>action('question-index',i,String(i+1),`${answer(item)?'answered ':''}${i===S.question?'current':''}`)).join('')}</div><p class="decision-note">Ответы сохраняются в этом браузере. Для передачи выгрузите JSON.</p></aside><article class="question-card"><div class="question-top"><span>${esc(q.id)} · ${esc(q.category||'Уточнение смысла')}</span><span>${S.question+1} из ${qs.length}</span></div><h2>${esc(q.title)}</h2><p class="question-context">${esc(q.question||q.context)}</p>${q.context&&q.context!==q.question?`<p class="question-context">${esc(q.context)}</p>`:''}<div class="question-evidence">${evidenceHtml((q.evidenceRefs||q.refs||[]).slice(0,2))}</div>${(q.evidenceRefs||q.refs||[]).length>2?`<details class="quote-disclosure"><summary>Остальные основания</summary>${evidenceHtml((q.evidenceRefs||q.refs).slice(2))}</details>`:''}<div class="options">${(q.options||[]).map((option,i)=>{const oid=option.id||String(i+1);return `<button class="option ${a?.option===oid?'selected':''}" data-action="answer" data-value="${esc(oid)}" aria-pressed="${a?.option===oid}"><span>${String.fromCharCode(65+i)}</span><div><b>${esc(option.label)}</b>${option.impact||option.description?`<p>${esc(option.impact||option.description)}</p>`:''}</div></button>`}).join('')}</div><label class="subtle" for="question-comment">Комментарий или своя формулировка</label><textarea class="question-comment" id="question-comment" placeholder="Дополнительные условия, ссылка на решение, нужная формулировка…">${esc(a?.comment||'')}</textarea><div class="question-actions">${action('question-step','-1','← Предыдущий')}<div>${action('save-question-comment','','Сохранить комментарий')}${action('question-step','1','Следующий →','button primary')}</div></div>${q.requirementIds?.length?`<div class="related">${q.requirementIds.filter(id=>findRow(id)||(DB.meta.otherRequirementIds||[]).includes(id)).map(id=>action('requirement',id,esc(id))).join('')}</div>`:''}<p class="decision-note">${a?'Ответ сохранен. При изменении решения можно выбрать другой вариант.':'Пока решения нет. Выберите вариант, добавьте свою формулировку или перейдите дальше.'}</p></article></div>`}
function renderGlossary(){return `<div class="section-title"><div><h2>Термины и границы объектов</h2><p>Определение, употребление и полномочие проверяются отдельно. Предлагаемое уточнение не выдается за цитату источника.</p></div><small>4 термина · 4 документа</small></div>${DB.meta.glossary.map(term=>`<section class="glossary-term"><div class="section-title"><h2>${esc(term.term)}</h2>${action('question-open','GQ'+term.id.slice(1),'Карточка решения ↗')}</div><p>${esc(term.conclusion)}</p><div class="table-wrap"><table><thead><tr><th>Документ</th><th>Что установлено</th></tr></thead><tbody>${[...term.documents].reverse().map(d=>`<tr><th>${SOURCE[d.source]}</th><td><p>${esc(d.finding)}</p><details class="quote-disclosure"><summary>Цитаты · ${d.refs.length}</summary>${evidenceHtml(d.refs)}</details></td></tr>`).join('')}</tbody></table></div><div class="missing"><strong>Что нужно определить</strong><p>${esc(term.unresolved)}</p></div>${term.notLostRequirement?`<p class="atlas-note">${esc(term.notLostRequirement)}</p>`:''}</section>`).join('')}`}
function renderMethods(){return `<div class="section-title"><div><h2>Источники и правила анализа</h2><p>Основания, границы выводов и история проверки.</p></div>${action('export-decisions','','Выгрузить рецензии')}</div><div class="method-grid"><section><h3>Два направления сверки</h3><p><b>Основания нового ФТТ:</b> проверяется, все ли существенные условия нового требования заданы в каждом прежнем документе. Более узкий новый пункт может иметь полное основание в широком исходном.</p><p><b>Сохранность ДТ 2.5:</b> проверяется обратное: все ли условия исходного требования сохранены в новом ФТТ. Здесь ищутся сокращения, пропуски и учет в общих компонентах.</p><p>Для остальных направлений используются только С39 и ФТТ 57.1. ДТ 2.5 относится к ЦМПОН.</p></section><section><h3>Как читаются оценки</h3><ul><li><b>Есть прямо:</b> действие, объект, участники и существенные ограничения подтверждены явными положениями.</li><li><b>Есть частично:</b> функция описана, но часть условий нового требования не подтверждена.</li><li><b>Только косвенно:</b> есть связанная функция или общий механизм, но требуется расширительная трактовка.</li><li><b>Не найдено:</b> в проверенной редакции подтверждающее положение не обнаружено.</li></ul><p>Лексическое сходство используется для поиска кандидатов. Оно не считается доказательством покрытия.</p></section><section><h3>Смысл и область действия</h3><p>Мобильный браузер и мобильное приложение проверяются отдельно. Утверждение каталога не подменяет утверждение выборки. Общая роль не подтверждает право просмотра защищенных данных. Пилот одного обследования не доказывает охват всех обследований.</p><p>Оценивается функциональное содержание. Различие очередей из заголовков отражается отдельно; сроки и ограничения, прямо записанные внутри требования, входят в оценку покрытия.</p><p>§4 содержит функции, заявленные в ФТТ как реализованные. Факт реализации и приемки этим анализом не подтверждается.</p></section><section><h3>Нумерация и полнота</h3><p>Идентификаторы «ФТТ-…» сохранены в том виде, как они даны в документе. Номер пункта оглавления показан отдельным полем.</p><p>«НФ-…»: редакционное обозначение атласа для требования без собственного идентификатора. Это не номер заказчика. У каждого такого пункта сохранен точный абзац источника.</p><p>Перечисления и обязательные продолжения учитываются вместе с родительским требованием. Описательные таблицы и контрольные показатели отделены от статистики функциональных требований.</p><p>Коды NEW-P, FTT-P, DT25-P и C39-P обозначают порядковые абзацы проверенной копии, T/R обозначают таблицу и строку. Это внутренние якоря цитат, а не номера страниц или официальные пункты документа.</p></section><section><h3>Проверенные редакции</h3>${DB.meta.sourceDocs.map(d=>`<div class="source-file"><strong>${esc(d.title||SOURCE[d.id])}</strong><p>${esc(d.originalFilename||d.filename)}</p><code>SHA-256: ${esc(d.sha256)}</code></div>`).join('')}</section><section><h3>Что требует решения</h3><p>Вопросы показывают неоднозначность формулировок, отличие объема или необходимость выбрать методологическое правило. Они не означают согласованного исключения требования.</p><p>Причины исключения и решения о переносе нельзя восстановить по одному отсутствию текста. Для них нужны отдельные документы или подтверждение функционального заказчика.</p><p>Рецензии и ответы хранятся отдельно от исходного анализа. После выгрузки решений можно подготовить следующую проверенную редакцию.</p><p><a href="./atlas-legacy.html">Открыть прежний атлас 2.0.2 ↗</a></p></section></div><p class="atlas-note"><a href="./docs/atlas-2026-release.md" download>Протокол проверки, итоги и методика (.md) ↓</a></p>${DB.meta.auditSummary?`<div class="notice">${esc(DB.meta.auditSummary)}</div>`:''}`}
function render(){if(!DB.meta)return;renderChrome();let html;if(S.workspace==='other'&&!DB.other){html='<div class="loading" role="status"><h2>Загружаем другие направления</h2><p>Отдельный каталог и две оценки по каждому требованию.</p></div>';ensureOther()}else html=S.view==='map'?renderMap():S.view==='requirements'||S.view==='reverse'?renderTable():S.view==='cosmos'?renderGeo():S.view==='questions'?renderQuestions():S.view==='glossary'?renderGlossary():S.view==='stats'?renderStats():renderMethods();$('content').innerHTML=html;if(S.view==='cosmos')mountGeo();hash()}
async function fetchData(name){const response=await fetch(ROOT+name+'.json?v=20261104',{cache:'no-cache'});if(!response.ok)throw new Error(`${name}: HTTP ${response.status}`);return response.json()}
async function ensureOther(){if(DB.other)return DB.other;if(!otherPromise)otherPromise=fetchData('other').then(rows=>{DB.other=rows;render();return rows}).catch(error=>{otherPromise=null;$('content').innerHTML=`<div class="loading"><h2>Не удалось загрузить каталог</h2><p>${esc(error.message)}</p>${action('reload','','Повторить загрузку')}</div>`;return null});return otherPromise}
function setView(view){const allowed=['map','requirements','cosmos','reverse','questions','stats','methods','glossary'];if(!allowed.includes(view))return;if(S.workspace==='other'&&['cosmos','reverse','glossary'].includes(view))view='map';if(S.view==='reverse'&&view!=='reverse')S.source='ftt571';S.view=view;S.page=1;S.status='all';S.section='all';S.queue='all';S.confidence='all';S.group='all';S.concept=null;$('nav').classList.remove('open');$('mobile-menu').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'})}
function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function download(name,contents,type){const blob=new Blob([contents],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function exportCsv(){const rows=filtered(),srcs=sourceList();if(!rows.length){toast('Нет требований для выгрузки');return}const fields=['ID','ID документа или атласа','Пункт оглавления','Название раздела','Очередь / статус','Требование','Продолжение',...srcs.flatMap(s=>[SOURCE[s]+': оценка',SOURCE[s]+': достоверность',SOURCE[s]+': основание',SOURCE[s]+': пробел',SOURCE[s]+': ссылки',SOURCE[s]+': отличие области'])];const lines=[fields,...rows.map(r=>[r.id,r.numbered===false?'Атлас':'Документ',r.section,r.sectionTitle,queueLabel(r),r.text,r.continuation||'',...srcs.flatMap(s=>{const m=mapping(r,s);return[LABEL[m.status],m.confidence,m.reason,m.missing,(m.refs||[]).join('; '),m.scopeDifference||'']})])];download(`Atlas_${S.workspace}_${S.view}_20261104.csv`,'\uFEFF'+lines.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast(`Выгружено требований: ${rows.length}`)}
function exportDecisions(){
 const questionById=new Map(DB.questions.map(q=>[q.id,q]));
 const answers=Object.fromEntries(Object.entries(LOCAL.answers).map(([id,saved])=>{
  const q=questionById.get(id),current=!!q&&(!q.signature||saved.signature===q.signature),status=!q?'orphaned':current?'current':'stale';
  const options=current?q.options:saved.questionSnapshot?.options;
  return [id,{...saved,status,hasDecision:current?!!answer(q):!!(saved.option||(typeof saved.comment==='string'&&saved.comment.trim())),currentSignature:q?.signature??null,currentQuestion:q?{id:q.id,scope:q.scope,title:q.title,question:q.question}:null,selectedOptionLabel:options?.find(o=>o.id===saved.option)?.label??null}];
 }));
 download('Atlas_decisions_20261104.json',JSON.stringify({schema:'atlas-review-v2',analysisVersion:DB.meta.version,exportedAt:new Date().toISOString(),notes:LOCAL.notes,answers},null,2),'application/json');
 toast('Решения и рецензии выгружены');
}
async function copyDetail(){let text='';if(S.selected?.kind==='requirement'){const r=findRow(S.selected.id);text=[r.id,'Пункт '+r.section+' '+r.sectionTitle,...(r.source==='dt25'?[]:[queueLabel(r)]),r.text,r.continuation||'',...Object.keys(r.maps||{}).map(src=>{const m=mapping(r,src);return`${SOURCE[src]}: ${LABEL[m.status]}\nДостоверность: ${m.confidence}\n${m.reason}\n${m.scopeDifference?'Область и очередь: '+m.scopeDifference+'\n':''}${m.missing?'Не подтверждено: '+m.missing+'\n':''}${(m.refs||[]).join('; ')}`})].join('\n\n')}else if(S.selected?.kind==='concept'){const c=DB.meta.concepts.find(c=>c.id===S.selected.id);text=c.id+'. '+c.title+'\n'+(S.selected.rowIds||DB.cmpon.filter(r=>(r.concepts||[]).includes(c.id)).map(r=>r.id)).join('; ')}try{await navigator.clipboard.writeText(text);toast('Текст и ссылки скопированы')}catch{const t=document.createElement('textarea');t.value=text;t.setAttribute('aria-label','Текст для копирования');$('detail-body').prepend(t);t.focus();t.select();toast('Текст выделен. Нажмите Ctrl+C или ⌘C.')}}
function currentQuestion(){return questions()[S.question]}
function saveQuestion(option){
 const q=currentQuestion();if(!q)return false;
 const prev=answer(q)||{},comment=$('question-comment')?.value??prev.comment??'',chosen=option??prev.option??null;
 if(!(q.options||[]).some(o=>o.id===chosen)&&!comment.trim()){toast('Выберите вариант или добавьте комментарий');return false}
 const value={option:chosen,comment,signature:q.signature||'',analysisVersion:DB.meta.version,questionSnapshot:{title:q.title,question:q.question,scope:q.scope,options:(q.options||[]).map(o=>({...o})),requirementIds:[...(q.requirementIds||[])],evidenceRefs:[...(q.evidenceRefs||[])]},updatedAt:new Date().toISOString()};
 if(!saveEntry('answers',q.id,value))return false;
 render();return true;
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action:a,value:v}=b.dataset;if(a==='workspace'){S.workspace=v==='other'?'other':'cmpon';S.questionSection='all';S.questionFilter='all';S.question=0;S.source='ftt571';S.view='map';reset()}else if(a==='view')setView(v);else if(a==='filtered-requirements'){S.view='requirements';S.page=1;render()}else if(a==='requirement')openRequirement(v);else if(a==='concept')openConcept(v);else if(a==='concept-filter'){$('detail').close();S.concept=v;S.view='requirements';S.group='all';S.page=1;render()}else if(a==='close')$('detail').close();else if(a==='copy')copyDetail();else if(a==='metric'){S.status=v;S.view=S.view==='reverse'?'reverse':'requirements';S.page=1;render()}else if(a==='status'){S.status=v;S.page=1;render()}else if(a==='reset')reset();else if(a==='clear-concept'){S.concept=null;render()}else if(a==='group'){S.group=v;S.page=1;render()}else if(a==='chapter'){S.section=v;S.view='requirements';S.page=1;render()}else if(a==='page'){S.page+=Number(v);render();$('content').scrollIntoView({block:'start'})}else if(a==='export')exportCsv();else if(a==='export-decisions')exportDecisions();else if(a==='save-review'){if(saveEntry('notes',v,{status:$('review-state').value,text:$('review-note').value,analysisVersion:DB.meta.version,updatedAt:new Date().toISOString()}))toast('Рецензия сохранена')}else if(a==='question-filter'){S.questionFilter=v;if(v==='all')S.questionSection='all';S.question=0;render()}else if(a==='question-index'){S.question=Number(v);render()}else if(a==='question-step'){S.question+=Number(v);render();$('content').scrollIntoView({block:'start'})}else if(a==='answer')saveQuestion(v);else if(a==='save-question-comment'){if(saveQuestion())toast('Комментарий сохранен')}else if(a==='question-open'){const q=DB.questions.find(q=>q.id===v);if(q){$('detail').close();S.workspace=q.scope||'cmpon';S.view='questions';S.questionFilter='all';S.questionSection='all';S.question=questions().findIndex(q=>q.id===v);render()}}else if(a==='geo-land'){S.geo=v;render()}else if(a==='geo-reset'){S.geo=null;render()}else if(a==='geo-zoom'){const svg=$('geo-map');if(svg){const box=svg.getAttribute('viewBox').split(' ').map(Number),f=v==='in'?.7:1.4,w=Math.min(1800,Math.max(120,box[2]*f)),h=w*box[3]/box[2];svg.setAttribute('viewBox',[box[0]+(box[2]-w)/2,box[1]+(box[3]-h)/2,w,h].join(' '))}}else if(a==='reload')location.reload()});
document.addEventListener('change',e=>{if(e.target.id==='question-section'){S.questionSection=e.target.value;S.question=0;render()}else if(e.target.id==='scope'){S.source=e.target.value;S.status='all';S.page=1;render()}else if(e.target.id==='section-filter'){S.section=e.target.value;S.page=1;render()}else if(e.target.id==='queue-filter'){S.queue=e.target.value;S.page=1;render()}else if(e.target.id==='confidence-filter'){S.confidence=e.target.value;S.page=1;render()}});
let searchTimer;$('search').addEventListener('input',e=>{clearTimeout(searchTimer);const value=e.target.value;searchTimer=setTimeout(()=>{S.query=value;S.page=1;render()},180)});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/input|textarea|select/i.test(e.target.tagName)){e.preventDefault();$('search').focus()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click()}});
$('mobile-menu').addEventListener('click',()=>{const isOpen=$('nav').classList.toggle('open');$('mobile-menu').setAttribute('aria-expanded',String(isOpen))});
$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close()}});
window.addEventListener('hashchange',()=>{if(location.hash==='#content')return;readHash();render()});
async function boot(){try{const [meta,cmpon,reverse,evidence,questions]=await Promise.all(['meta','cmpon','reverse','evidence','questions'].map(fetchData));DB={...DB,meta,cmpon,reverse,evidence,questions};readHash();render();if(S.workspace==='other')await ensureOther();window.__atlas2026={version:meta.version,counts:{cmpon:cmpon.length,reverse:reverse.length,questions:questions.length},state:S,health:()=>({missingEvidence:allRows().flatMap(r=>Object.values(r.maps||{}).flatMap(m=>m.refs||[])).filter(k=>!DB.evidence[k]),scope:S.workspace,rows:currentRows().length})}}catch(error){$('content').innerHTML=`<div class="loading" role="alert"><h2>Не удалось загрузить атлас</h2><p>${esc(error.message)}</p>${action('reload','','Повторить загрузку')}</div>`}}
boot();
})();
